//! Native plugin libraries (NEP mode).
//!
//! The host loads platform libraries at runtime: `.so` (Linux), `.dylib`
//! (macOS), `.dll` (Windows). A library exports two C-ABI symbols, normally
//! generated by [`export_plugin!`](crate::export_plugin):
//!
//! * `thenodes_plugin_abi_version() -> u32`, checked before any other plugin
//!   code is invoked;
//! * `register_plugin(api: *const PluginRegistrarApi) -> u32`, which registers
//!   the library's handlers and returns a [`RegistrationStatus`] code.
//!
//! The registrar table has a C layout. The objects it transfers use the Rust
//! ABI of the exact TheNodes release, Rust toolchain, target, dependency
//! build, and feature set: host and plugins must be built together, with the
//! same global allocator and with unwinding panics. The ABI version is a
//! compatibility check, not authentication; loading a library can run its
//! native constructors before the check.
//!
//! Loaded libraries are pinned: their code stays mapped until the process
//! exits, whether registration succeeds or fails.
//!
//! On Unix a library is loaded only if no other user could have written or
//! replaced it: the file, and every directory above it once symlinks are
//! resolved, must be owned by the node's user or root and not writable by
//! anyone else. A directory with the sticky bit (such as `/tmp`) may be
//! writable by others, since they cannot rename or remove entries they do not
//! own. Group write is accepted when the group is the owner's private group,
//! the default under `umask 002`, and the entry has no POSIX ACL: with an
//! ACL the group bits are its mask, which may grant write to other users.
//! ACLs on systems other than Linux are not checked.

use std::ffi::c_void;
use std::fmt;
use std::fs;
use std::io;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use libloading::Library;

use super::lifecycle::{PluginRegistrationError, DEFAULT_RUNTIME_WORKERS};
use super::manager::{PluginManager, RegistrationIndex};
use super::runtime::{
    LibraryRuntime, NativeRegistration, PluginAdapter, PluginDescriptor, RuntimeSource,
};
use super::Plugin;

/// Version of the native plugin boundary. Bumped whenever the registrar,
/// the transferred endpoint, the `Plugin` trait, or the runtime contract changes.
pub const PLUGIN_ABI_VERSION: u32 = 4;

const ABI_VERSION_SYMBOL: &str = "thenodes_plugin_abi_version";
const REGISTER_SYMBOL: &str = "register_plugin";

type AbiVersionFn = unsafe extern "C" fn() -> u32;
type RegisterPluginFn = unsafe extern "C" fn(api: *const PluginRegistrarApi) -> u32;
type RegisterHandlerFn =
    unsafe extern "C" fn(host_context: *mut c_void, registration: *mut c_void) -> u32;

/// Fixed-width outcome of a native registration call.
#[repr(u32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RegistrationStatus {
    Ok = 0,
    NullApi = 1,
    AbiMismatch = 2,
    MissingHandler = 3,
    NullContext = 4,
    InvalidPluginId = 5,
    DuplicatePluginId = 6,
    DuplicatePromptPrefix = 7,
    ConflictingDefaults = 8,
    NoPlugins = 9,
    PluginError = 10,
    Panicked = 11,
    InvalidRuntimeConfig = 12,
    RegistrationClosed = 13,
    HostError = 14,
    Unknown = 15,
}

impl RegistrationStatus {
    pub fn code(self) -> u32 {
        self as u32
    }

    pub fn from_code(code: u32) -> Self {
        match code {
            0 => Self::Ok,
            1 => Self::NullApi,
            2 => Self::AbiMismatch,
            3 => Self::MissingHandler,
            4 => Self::NullContext,
            5 => Self::InvalidPluginId,
            6 => Self::DuplicatePluginId,
            7 => Self::DuplicatePromptPrefix,
            8 => Self::ConflictingDefaults,
            9 => Self::NoPlugins,
            10 => Self::PluginError,
            11 => Self::Panicked,
            12 => Self::InvalidRuntimeConfig,
            13 => Self::RegistrationClosed,
            14 => Self::HostError,
            _ => Self::Unknown,
        }
    }
}

/// Registrar table passed to a library's `register_plugin` export.
///
/// The pointer is valid only for the duration of that synchronous call.
/// Plugins must not retain it; registration closes when the call returns.
#[repr(C)]
pub struct PluginRegistrarApi {
    abi_version: u32,
    host_context: *mut c_void,
    register_handler: Option<RegisterHandlerFn>,
    reserved: [usize; 4],
}

impl PluginRegistrarApi {
    pub fn abi_version(&self) -> u32 {
        self.abi_version
    }

    /// # Safety
    /// `ptr` must be null or point to a valid `PluginRegistrarApi`.
    pub unsafe fn from_raw<'a>(
        ptr: *const PluginRegistrarApi,
    ) -> Result<&'a PluginRegistrarApi, RegistrationStatus> {
        ptr.as_ref().ok_or(RegistrationStatus::NullApi)
    }

    fn for_host(staging: &mut LibraryStaging) -> Self {
        Self {
            abi_version: PLUGIN_ABI_VERSION,
            host_context: staging as *mut LibraryStaging as *mut c_void,
            register_handler: Some(register_handler_thunk),
            reserved: [0; 4],
        }
    }
}

/// Collects the handlers a native library registers.
///
/// Used inside the plugin's `export_plugin!` registration function.
pub struct NativeRegistrar {
    plugins: Vec<Box<dyn Plugin>>,
    runtime_workers: usize,
}

impl NativeRegistrar {
    fn new() -> Self {
        Self {
            plugins: Vec::new(),
            runtime_workers: DEFAULT_RUNTIME_WORKERS,
        }
    }

    /// Register a handler. Every handler of a library shares the library's
    /// runtime. The host validates IDs, prompt prefixes, and defaults; one
    /// rejected handler fails the whole library.
    pub fn register(&mut self, plugin: Box<dyn Plugin>) {
        self.plugins.push(plugin);
    }

    /// Worker threads of this library's runtime. Defaults to
    /// [`DEFAULT_RUNTIME_WORKERS`].
    pub fn set_runtime_workers(&mut self, workers: usize) -> Result<(), PluginRegistrationError> {
        if workers == 0 {
            return Err(PluginRegistrationError::InvalidRuntimeConfig(
                "runtime workers must be at least 1".to_string(),
            ));
        }
        self.runtime_workers = workers;
        Ok(())
    }
}

/// Plugin-side registration entry point used by [`export_plugin!`](crate::export_plugin).
///
/// Runs inside the plugin's code copy. Panics are caught here, and every
/// outcome is returned as a status code.
///
/// # Safety
/// `api` must be null or point to the registrar table supplied by the host for
/// the duration of this call.
#[doc(hidden)]
pub unsafe fn register_library<F>(api: *const PluginRegistrarApi, register: F) -> u32
where
    F: FnOnce(&mut NativeRegistrar) -> Result<(), PluginRegistrationError>,
{
    match catch_unwind(AssertUnwindSafe(|| register_library_inner(api, register))) {
        Ok(status) => status.code(),
        Err(_) => RegistrationStatus::Panicked.code(),
    }
}

unsafe fn register_library_inner<F>(
    api: *const PluginRegistrarApi,
    register: F,
) -> RegistrationStatus
where
    F: FnOnce(&mut NativeRegistrar) -> Result<(), PluginRegistrationError>,
{
    let api = match PluginRegistrarApi::from_raw(api) {
        Ok(api) => api,
        Err(status) => return status,
    };
    if api.abi_version != PLUGIN_ABI_VERSION {
        return RegistrationStatus::AbiMismatch;
    }
    let Some(handler) = api.register_handler else {
        return RegistrationStatus::MissingHandler;
    };
    if api.host_context.is_null() {
        return RegistrationStatus::NullContext;
    }

    let mut registrar = NativeRegistrar::new();
    if let Err(error) = register(&mut registrar) {
        return error.status();
    }
    if registrar.plugins.is_empty() {
        return RegistrationStatus::NoPlugins;
    }

    // The runtime itself is created when the first handler starts, never
    // during registration.
    let library = Arc::new(LibraryRuntime::new(registrar.runtime_workers));
    for plugin in registrar.plugins {
        let plugin: Arc<dyn Plugin> = Arc::from(plugin);
        let descriptor = PluginDescriptor::read(plugin.as_ref());
        let endpoint =
            PluginAdapter::new(plugin, &descriptor, RuntimeSource::Library(library.clone()));
        let registration = Box::new(NativeRegistration {
            descriptor,
            endpoint: Box::new(endpoint),
        });
        // The host takes ownership of the registration whatever the outcome.
        let status = RegistrationStatus::from_code(handler(
            api.host_context,
            Box::into_raw(registration) as *mut c_void,
        ));
        if status != RegistrationStatus::Ok {
            return status;
        }
    }
    RegistrationStatus::Ok
}

/// Export the native plugin entry points of a `cdylib`.
///
/// ```ignore
/// fn register(registrar: &mut thenodes::plugin_host::NativeRegistrar)
///     -> Result<(), thenodes::plugin_host::PluginRegistrationError>
/// {
///     registrar.register(Box::new(MyPlugin::new()));
///     Ok(())
/// }
///
/// thenodes::export_plugin!(register);
/// ```
#[macro_export]
macro_rules! export_plugin {
    ($register:expr) => {
        /// Plugin ABI version of the TheNodes copy this library was built with.
        #[no_mangle]
        pub extern "C" fn thenodes_plugin_abi_version() -> u32 {
            $crate::plugin_host::PLUGIN_ABI_VERSION
        }

        /// Register this library's plugin handlers with the host.
        ///
        /// # Safety
        ///
        /// `api` must be the registrar table supplied by a TheNodes host for
        /// the duration of this call.
        #[no_mangle]
        pub unsafe extern "C" fn register_plugin(
            api: *const $crate::plugin_host::PluginRegistrarApi,
        ) -> u32 {
            $crate::plugin_host::register_library(api, $register)
        }
    };
}

/// Host-side staging area for one library's registrations. Nothing is added to
/// the manager until the whole library registered successfully.
struct LibraryStaging {
    index: RegistrationIndex,
    staged: Vec<NativeRegistration>,
    error: Option<PluginRegistrationError>,
}

impl LibraryStaging {
    fn stage(&mut self, registration: NativeRegistration) -> RegistrationStatus {
        if self.error.is_some() {
            return RegistrationStatus::RegistrationClosed;
        }
        match self.index.check(&registration.descriptor) {
            Ok(()) => {
                self.index.insert(&registration.descriptor);
                self.staged.push(registration);
                RegistrationStatus::Ok
            }
            Err(error) => {
                let status = error.status();
                self.error = Some(error);
                status
            }
        }
    }
}

unsafe extern "C" fn register_handler_thunk(ctx: *mut c_void, registration: *mut c_void) -> u32 {
    let result = catch_unwind(AssertUnwindSafe(|| {
        if ctx.is_null() || registration.is_null() {
            return RegistrationStatus::HostError;
        }
        let registration = Box::from_raw(registration as *mut NativeRegistration);
        let staging = &mut *(ctx as *mut LibraryStaging);
        staging.stage(*registration)
    }));
    result.unwrap_or(RegistrationStatus::HostError).code()
}

/// Paths of libraries pinned by this process.
static PINNED_LIBRARIES: Mutex<Vec<PathBuf>> = Mutex::new(Vec::new());

/// Keep a loaded library mapped until process exit. Called immediately after a
/// successful load, before any of its code or objects can escape.
fn pin_library(library: Library, path: &Path) -> &'static Library {
    PINNED_LIBRARIES
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .push(path.to_path_buf());
    Box::leak(Box::new(library))
}

/// Number of native libraries pinned by this process.
pub fn pinned_library_count() -> usize {
    PINNED_LIBRARIES
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .len()
}

/// A library whose handlers were registered.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LoadedLibrary {
    pub path: PathBuf,
    pub plugin_ids: Vec<String>,
}

/// Errors from loading a native plugin library.
#[derive(Debug)]
pub enum PluginLoadError {
    Discover {
        dir: PathBuf,
        source: io::Error,
    },
    Open {
        path: PathBuf,
        reason: String,
    },
    /// Another user could have written or replaced the library: `offending`,
    /// the library itself or a directory above it, is owned by another user
    /// or writable by others.
    UnsafePath {
        path: PathBuf,
        offending: PathBuf,
        reason: &'static str,
    },
    MissingSymbol {
        path: PathBuf,
        symbol: &'static str,
    },
    AbiMismatch {
        path: PathBuf,
        expected: u32,
        found: u32,
    },
    Registration {
        path: PathBuf,
        error: PluginRegistrationError,
    },
}

impl fmt::Display for PluginLoadError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PluginLoadError::Discover { dir, source } => {
                write!(f, "failed to read plugin directory {}: {source}", dir.display())
            }
            PluginLoadError::Open { path, reason } => {
                write!(f, "failed to load plugin library {}: {reason}", path.display())
            }
            PluginLoadError::UnsafePath {
                path,
                offending,
                reason,
            } => write!(
                f,
                "refusing plugin library {}: {} {reason}; the library and every directory above it must be owned by the node's user or root and not writable by other users",
                path.display(),
                offending.display()
            ),
            PluginLoadError::MissingSymbol { path, symbol } => write!(
                f,
                "plugin library {} does not export `{symbol}`; rebuild it against this TheNodes release",
                path.display()
            ),
            PluginLoadError::AbiMismatch {
                path,
                expected,
                found,
            } => write!(
                f,
                "plugin library {} uses plugin ABI {found}, host requires {expected}",
                path.display()
            ),
            PluginLoadError::Registration { path, error } => write!(
                f,
                "plugin library {} failed to register: {error}",
                path.display()
            ),
        }
    }
}

impl std::error::Error for PluginLoadError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            PluginLoadError::Discover { source, .. } => Some(source),
            PluginLoadError::Registration { error, .. } => Some(error),
            _ => None,
        }
    }
}

/// Loads native plugin libraries into a [`PluginManager`].
#[derive(Default)]
pub struct PluginLoader {
    loaded: Vec<LoadedLibrary>,
}

impl PluginLoader {
    pub fn new() -> Self {
        Self::default()
    }

    fn is_dynamic_lib(path: &Path) -> bool {
        match path.extension().and_then(|e| e.to_str()) {
            Some(ext) => {
                let ext = ext.to_ascii_lowercase();
                ext == "so" || ext == "dylib" || ext == "dll"
            }
            None => false,
        }
    }

    /// Dynamic libraries in `dir`, sorted by path. Sorting makes logs and tests
    /// reproducible; it does not define dependencies or precedence.
    pub fn discover<P: AsRef<Path>>(dir: P) -> io::Result<Vec<PathBuf>> {
        let mut paths = Vec::new();
        for entry in fs::read_dir(dir)? {
            let path = entry?.path();
            if Self::is_dynamic_lib(&path) {
                paths.push(path);
            }
        }
        paths.sort();
        Ok(paths)
    }

    /// Load every library in `dir` in sorted order. Stops at the first library
    /// that fails; libraries loaded before it stay registered.
    pub fn load_plugins<P: AsRef<Path>>(
        &mut self,
        plugin_dir: P,
        manager: &mut PluginManager,
    ) -> Result<Vec<LoadedLibrary>, PluginLoadError> {
        let dir = plugin_dir.as_ref();
        let paths = Self::discover(dir).map_err(|source| PluginLoadError::Discover {
            dir: dir.to_path_buf(),
            source,
        })?;
        let mut loaded = Vec::new();
        for path in paths {
            loaded.push(self.load_library(&path, manager)?);
        }
        Ok(loaded)
    }

    /// Load one library and register all of its handlers, or none of them.
    pub fn load_library<P: AsRef<Path>>(
        &mut self,
        path: P,
        manager: &mut PluginManager,
    ) -> Result<LoadedLibrary, PluginLoadError> {
        let path = path.as_ref();
        let registration_error = |error| PluginLoadError::Registration {
            path: path.to_path_buf(),
            error,
        };
        if !manager.registration_open() {
            return Err(registration_error(
                PluginRegistrationError::RegistrationClosed,
            ));
        }
        // Load the checked file itself, so a symlink replaced after the check
        // does not matter.
        let checked = check_library_path(path)?;

        // SAFETY: loading a library runs its initializers. Plugin libraries are
        // trusted code; see the module documentation.
        let library = unsafe { Library::new(&checked) }.map_err(|error| PluginLoadError::Open {
            path: path.to_path_buf(),
            reason: error.to_string(),
        })?;
        let library = pin_library(library, path);

        // SAFETY: the symbol types follow the ABI contract checked below. The
        // library is pinned, so the function pointers stay valid.
        let abi_version: AbiVersionFn = unsafe {
            *library
                .get::<AbiVersionFn>(ABI_VERSION_SYMBOL.as_bytes())
                .map_err(|_| PluginLoadError::MissingSymbol {
                    path: path.to_path_buf(),
                    symbol: ABI_VERSION_SYMBOL,
                })?
        };
        let found = unsafe { abi_version() };
        if found != PLUGIN_ABI_VERSION {
            return Err(PluginLoadError::AbiMismatch {
                path: path.to_path_buf(),
                expected: PLUGIN_ABI_VERSION,
                found,
            });
        }
        let register: RegisterPluginFn = unsafe {
            *library
                .get::<RegisterPluginFn>(REGISTER_SYMBOL.as_bytes())
                .map_err(|_| PluginLoadError::MissingSymbol {
                    path: path.to_path_buf(),
                    symbol: REGISTER_SYMBOL,
                })?
        };

        let mut staging = LibraryStaging {
            index: manager.registration_index().clone(),
            staged: Vec::new(),
            error: None,
        };
        let api = PluginRegistrarApi::for_host(&mut staging);
        // SAFETY: `api` and `staging` outlive this synchronous call.
        let status = RegistrationStatus::from_code(unsafe { register(&api) });
        let LibraryStaging { staged, error, .. } = staging;

        // A partial registration never becomes host configuration. Dropping
        // staged objects is safe because the library stays pinned.
        if let Some(error) = error {
            return Err(registration_error(error));
        }
        if status != RegistrationStatus::Ok {
            return Err(registration_error(match status {
                RegistrationStatus::NoPlugins => PluginRegistrationError::NoPlugins,
                RegistrationStatus::RegistrationClosed => {
                    PluginRegistrationError::RegistrationClosed
                }
                other => PluginRegistrationError::Native(other),
            }));
        }
        if staged.is_empty() {
            return Err(registration_error(PluginRegistrationError::NoPlugins));
        }

        let plugin_ids = manager
            .commit_native(path, staged)
            .map_err(registration_error)?;
        for plugin_id in &plugin_ids {
            println!("🔌 Loaded plugin '{}' from {}", plugin_id, path.display());
        }
        let loaded = LoadedLibrary {
            path: path.to_path_buf(),
            plugin_ids,
        };
        self.loaded.push(loaded.clone());
        Ok(loaded)
    }

    pub fn loaded(&self) -> &[LoadedLibrary] {
        &self.loaded
    }
}

/// The library's real path, if no other user could have written or replaced
/// it (see the module documentation).
#[cfg(unix)]
fn check_library_path(path: &Path) -> Result<PathBuf, PluginLoadError> {
    use std::os::unix::fs::MetadataExt;

    let open_error = |error: io::Error| PluginLoadError::Open {
        path: path.to_path_buf(),
        reason: error.to_string(),
    };
    let real_path = fs::canonicalize(path).map_err(open_error)?;
    let node_user = nix::unistd::geteuid().as_raw();
    for entry in real_path.ancestors() {
        let meta = fs::metadata(entry).map_err(open_error)?;
        let mode = meta.mode();
        let reason = if meta.uid() != node_user && meta.uid() != 0 {
            Some("is owned by another user")
        } else if meta.is_dir() && mode & 0o1000 != 0 {
            None
        } else if mode & 0o002 != 0 {
            Some("is writable by other users")
        } else if mode & 0o020 != 0 {
            // With an ACL the group bits are its mask, so the write access may
            // belong to other users or groups.
            match has_access_acl(entry) {
                Ok(true) => Some("has an ACL that may let other users write to it"),
                Err(_) => Some("has an ACL that cannot be read"),
                Ok(false) if !is_private_group(meta.uid(), meta.gid()) => {
                    Some("is writable by its group")
                }
                Ok(false) => None,
            }
        } else {
            None
        };
        if let Some(reason) = reason {
            return Err(PluginLoadError::UnsafePath {
                path: path.to_path_buf(),
                offending: entry.to_path_buf(),
                reason,
            });
        }
    }
    Ok(real_path)
}

#[cfg(not(unix))]
fn check_library_path(path: &Path) -> Result<PathBuf, PluginLoadError> {
    Ok(path.to_path_buf())
}

/// Whether `path` has a POSIX access ACL (`system.posix_acl_access`).
#[cfg(target_os = "linux")]
fn has_access_acl(path: &Path) -> io::Result<bool> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;

    let path = CString::new(path.as_os_str().as_bytes())
        .map_err(|_| io::Error::from(io::ErrorKind::InvalidInput))?;
    // SAFETY: both names are NUL-terminated; a null buffer of size 0 only
    // asks for the attribute's size.
    let size = unsafe {
        libc::getxattr(
            path.as_ptr(),
            c"system.posix_acl_access".as_ptr(),
            std::ptr::null_mut(),
            0,
        )
    };
    if size >= 0 {
        return Ok(true);
    }
    let error = io::Error::last_os_error();
    match error.raw_os_error() {
        Some(libc::ENODATA) | Some(libc::ENOTSUP) => Ok(false),
        _ => Err(error),
    }
}

/// Other systems keep ACLs apart from the mode bits; they are not checked.
#[cfg(all(unix, not(target_os = "linux")))]
fn has_access_acl(_path: &Path) -> io::Result<bool> {
    Ok(false)
}

/// Whether `gid` is the private group of user `uid`: the user's primary group,
/// named after the user and listing no other members.
#[cfg(unix)]
fn is_private_group(uid: u32, gid: u32) -> bool {
    use nix::unistd::{Gid, Group, Uid, User};

    let (Ok(Some(user)), Ok(Some(group))) = (
        User::from_uid(Uid::from_raw(uid)),
        Group::from_gid(Gid::from_raw(gid)),
    ) else {
        return false;
    };
    user.gid.as_raw() == gid
        && group.name == user.name
        && group.mem.iter().all(|member| *member == user.name)
}

#[cfg(all(test, unix))]
mod tests {
    use super::*;
    use std::os::unix::fs::{symlink, MetadataExt, PermissionsExt};

    fn set_mode(path: &Path, mode: u32) {
        fs::set_permissions(path, fs::Permissions::from_mode(mode)).unwrap();
    }

    fn directory_in(parent: &Path, name: &str, mode: u32) -> PathBuf {
        let dir = parent.join(name);
        fs::create_dir(&dir).unwrap();
        set_mode(&dir, mode);
        dir
    }

    fn library_in(dir: &Path, mode: u32) -> PathBuf {
        let path = dir.join("libplugin.so");
        fs::write(&path, b"not a library").unwrap();
        set_mode(&path, mode);
        path
    }

    fn offending(result: Result<PathBuf, PluginLoadError>) -> PathBuf {
        match result {
            Err(PluginLoadError::UnsafePath { offending, .. }) => offending,
            other => panic!("expected an unsafe path, got {other:?}"),
        }
    }

    #[test]
    fn a_library_others_can_write_or_replace_is_refused() {
        let root = tempfile::tempdir().unwrap();
        let plugins = directory_in(root.path(), "plugins", 0o755);
        let library = library_in(&plugins, 0o644);
        assert!(check_library_path(&library).is_ok());

        set_mode(&library, 0o646);
        assert_eq!(
            offending(check_library_path(&library)),
            fs::canonicalize(&library).unwrap()
        );
        set_mode(&library, 0o644);

        set_mode(&plugins, 0o757);
        assert_eq!(
            offending(check_library_path(&library)),
            fs::canonicalize(&plugins).unwrap()
        );

        // With the sticky bit, others cannot rename or remove the library.
        set_mode(&plugins, 0o1757);
        assert!(check_library_path(&library).is_ok());
    }

    #[test]
    fn group_write_is_accepted_only_for_the_owners_private_group() {
        let root = tempfile::tempdir().unwrap();
        let library = library_in(root.path(), 0o664);
        let meta = fs::metadata(&library).unwrap();
        assert_eq!(
            check_library_path(&library).is_ok(),
            is_private_group(meta.uid(), meta.gid())
        );
        if meta.uid() != 0 {
            assert!(!is_private_group(meta.uid(), 0), "root's group");
        }
    }

    /// Regression test: an ACL entry granting another user write shows only
    /// as group write, which passed for the owner's private group.
    #[cfg(target_os = "linux")]
    #[test]
    fn an_acl_that_lets_another_user_write_is_refused() {
        let root = tempfile::tempdir().unwrap();
        let library = library_in(root.path(), 0o644);
        let setfacl = |entry: &str| {
            std::process::Command::new("setfacl")
                .args(["-m", entry])
                .arg(&library)
                .status()
                .is_ok_and(|status| status.success())
        };
        if !setfacl("u:65534:rw") {
            eprintln!("setfacl is unavailable or the filesystem has no ACLs; skipped");
            return;
        }
        assert!(has_access_acl(&library).unwrap());
        assert_eq!(
            offending(check_library_path(&library)),
            fs::canonicalize(&library).unwrap()
        );

        // Without write in the ACL the mask has no write, and nobody else can write.
        assert!(setfacl("u:65534:r"));
        assert!(check_library_path(&library).is_ok());
    }

    #[test]
    fn symlinks_are_checked_and_loaded_at_their_target() {
        let root = tempfile::tempdir().unwrap();
        let elsewhere = directory_in(root.path(), "elsewhere", 0o757);
        let library = library_in(&elsewhere, 0o644);
        let plugins = directory_in(root.path(), "plugins", 0o755);
        let link = plugins.join("libplugin.so");
        symlink(&library, &link).unwrap();
        assert_eq!(
            offending(check_library_path(&link)),
            fs::canonicalize(&elsewhere).unwrap()
        );

        set_mode(&elsewhere, 0o755);
        assert_eq!(
            check_library_path(&link).unwrap(),
            fs::canonicalize(&library).unwrap()
        );
    }

    #[test]
    fn the_loader_refuses_an_unsafe_library_before_opening_it() {
        let root = tempfile::tempdir().unwrap();
        let library = library_in(root.path(), 0o666);
        let mut manager = PluginManager::new();
        let error = PluginLoader::new()
            .load_library(&library, &mut manager)
            .unwrap_err();
        assert!(
            matches!(error, PluginLoadError::UnsafePath { .. }),
            "{error:?}"
        );

        // Once safe, the file is opened, and fails as the non-library it is.
        set_mode(&library, 0o644);
        let error = PluginLoader::new()
            .load_library(&library, &mut manager)
            .unwrap_err();
        assert!(matches!(error, PluginLoadError::Open { .. }), "{error:?}");
    }
}
